export const LANGS = { en: EN, nl: NL };

// Ersetzt exakt die Texte aus der Liste; fehlende Texte werden gemeldet
export function applyPairs(src, pairs, label) {
  let out = src;
  const missing = [];
  for (const [a, b] of pairs) {
    if (!out.includes(a)) { missing.push(a.slice(0, 70)); continue; }
    out = out.split(a).join(b);
  }
  if (missing.length) console.warn(`Übersetzung ${label}: ${missing.length} Text(e) nicht gefunden:\n  - ` + missing.join('\n  - '));
  return out;
}
